'use strict';

const stringify = require('../stringify');

/**
 * Стрим для yandex-logger, позволяющий писать в stdout простой json.
 *
 * @param {YandexLoggerJsonStreamConfig} [config]
 * @returns {Object}
 */
module.exports = config => {
    config = config || {};

    let stream = config.stream || process.stdout;

    return {
        /**
         * @param {Object} record
         * @returns {undefined}
         */
        write(record) {
            stream.write(stringify(record) + '\n');
        },
    };
};

/**
 * @typedef {Object} YandexLoggerJsonStreamConfig
 * @property {String} stream - Writable stream, например, process.stdout
 */
